import{_ as n,o as r,c as i,ah as t}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"Recherche: Korruption von FPÖ und ÖVP in Regierungsverantwortung (Internationale Perspektiven)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/korruption-oevp-fpoe.md","filePath":"recherche/korruption-oevp-fpoe.md"}'),a={name:"recherche/korruption-oevp-fpoe.md"};function s(o,e,u,h,l,d){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="recherche-korruption-von-fpo-und-ovp-in-regierungsverantwortung-internationale-perspektiven" tabindex="-1">Recherche: Korruption von FPÖ und ÖVP in Regierungsverantwortung (Internationale Perspektiven) <a class="header-anchor" href="#recherche-korruption-von-fpo-und-ovp-in-regierungsverantwortung-internationale-perspektiven" aria-label="Permalink to &quot;Recherche: Korruption von FPÖ und ÖVP in Regierungsverantwortung (Internationale Perspektiven)&quot;">​</a></h1><p>Die politische Landschaft Österreichs wurde in den letzten Jahren von einer Reihe von Korruptionsvorwürfen und Skandalen erschüttert, die auch international Beachtung fanden. Insbesondere die Regierungszeiten, in denen FPÖ und ÖVP maßgeblich beteiligt waren, zogen die Kritik internationaler Organisationen und Medien auf sich.</p><h2 id="hauptkritikpunkte-internationaler-beobachter" tabindex="-1">Hauptkritikpunkte internationaler Beobachter <a class="header-anchor" href="#hauptkritikpunkte-internationaler-beobachter" aria-label="Permalink to &quot;Hauptkritikpunkte internationaler Beobachter&quot;">​</a></h2><h3 id="_1-greco-europarat-–-staatengruppe-gegen-korruption" tabindex="-1">1. GRECO (Europarat – Staatengruppe gegen Korruption) <a class="header-anchor" href="#_1-greco-europarat-–-staatengruppe-gegen-korruption" aria-label="Permalink to &quot;1. GRECO (Europarat – Staatengruppe gegen Korruption)&quot;">​</a></h3><p>Die GRECO-Berichte kritisieren Österreich seit Jahren für die schleppende Umsetzung von Antikorruptions-Empfehlungen.</p><ul><li><strong>Mangelnde Transparenz:</strong> Es gibt Defizite bei der Offenlegung von Nebentätigkeiten von Abgeordneten und mangelnde Regeln für Lobbying.</li><li><strong>Keine unabhängige Staatsanwaltschaft:</strong> Die Weisungsgebundenheit der Staatsanwaltschaft wird als Einfallstor für politischen Einfluss gesehen.</li><li><strong>Strategische Risikoanalyse fehlt:</strong> Insbesondere für Personen in obersten Exekutivfunktionen (Minister, Staatssekretäre) fehlt ein systematischer Ansatz zur Korruptionsrisikoanalyse.</li></ul><h3 id="_2-europaische-kommission-rechtsstaatlichkeitsberichte" tabindex="-1">2. Europäische Kommission (Rechtsstaatlichkeitsberichte) <a class="header-anchor" href="#_2-europaische-kommission-rechtsstaatlichkeitsberichte" aria-label="Permalink to &quot;2. Europäische Kommission (Rechtsstaatlichkeitsberichte)&quot;">​</a></h3><p>Die EU-Kommission thematisiert in ihren jährlichen Berichten wiederkehrend &quot;besorgniserregende Entwicklungen&quot;:</p><ul><li><strong>Politischer Druck auf die Justiz:</strong> Speziell die Wirtschafts- und Korruptionsstaatsanwaltschaft (WKStA) war wiederholt Ziel politischer Angriffe und des Versuchs der Einflussnahme.</li><li><strong>Fehlende unabhängige Bundesstaatsanwaltschaft:</strong> Die Forderung nach einer von politischem Einfluss unabhängigen Bundesstaatsanwaltschaft ist ein zentraler Punkt.</li><li><strong>Inseratenkorruption:</strong> Mangelnde Transparenz und hohe Staatsausgaben für Regierungsinserate werden als Mittel zur Medienbeeinflussung kritisiert.</li></ul><h3 id="_3-transparency-international-corruption-perceptions-index-cpi" tabindex="-1">3. Transparency International (Corruption Perceptions Index - CPI) <a class="header-anchor" href="#_3-transparency-international-corruption-perceptions-index-cpi" aria-label="Permalink to &quot;3. Transparency International (Corruption Perceptions Index - CPI)&quot;">​</a></h3><p>Österreichs Position im weltweiten Korruptionswahrnehmungsindex hat sich unter den genannten Regierungen deutlich verschlechtert.</p><ul><li><strong>Absturz im Ranking:</strong> Von Platz 15 im Jahr 2018 fiel Österreich auf einen historischen Tiefstand (z.B. Platz 25 im Jahr 2024), was auf die zahlreichen Skandale und die mangelnde Reformbereitschaft zurückgeführt wird.</li><li><strong>Gründe:</strong> Günstlingswirtschaft, persönliche Bereicherung und Versuche der politischen Einflussnahme auf unabhängige Medien sind wiederkehrende Stichworte.</li></ul><h3 id="_4-oecd-organisation-fur-wirtschaftliche-zusammenarbeit-und-entwicklung" tabindex="-1">4. OECD (Organisation für wirtschaftliche Zusammenarbeit und Entwicklung) <a class="header-anchor" href="#_4-oecd-organisation-fur-wirtschaftliche-zusammenarbeit-und-entwicklung" aria-label="Permalink to &quot;4. OECD (Organisation für wirtschaftliche Zusammenarbeit und Entwicklung)&quot;">​</a></h3><p>Die OECD fordert insbesondere eine Stärkung der Unabhängigkeit der Staatsanwaltschaft und eine präzisere Handhabung von Rechtshilfeersuchen, um die Verfolgung von Korruptionsdelikten nicht zu behindern.</p><h3 id="_5-internationale-medien-und-der-ibiza-skandal" tabindex="-1">5. Internationale Medien und der Ibiza-Skandal <a class="header-anchor" href="#_5-internationale-medien-und-der-ibiza-skandal" aria-label="Permalink to &quot;5. Internationale Medien und der Ibiza-Skandal&quot;">​</a></h3><p>Der <strong>Ibiza-Skandal (Mai 2019)</strong>, aufgedeckt durch den Spiegel und die Süddeutsche Zeitung, zeigte den damaligen Vizekanzler Heinz-Christian Strache (FPÖ), wie er einer vermeintlichen russischen Oligarchin Staatsaufträge in Aussicht stellte. Dies führte international zu großer Empörung und dem Zusammenbruch der Regierung. Der Skandal wurde weltweit von renommierten Medien wie The Guardian, The New York Times und Le Monde aufgegriffen und als schwerwiegender Angriff auf die demokratischen Institutionen Österreichs bewertet.</p><h3 id="zusammenfassende-vorwurfe-auswahl" tabindex="-1">Zusammenfassende Vorwürfe (Auswahl): <a class="header-anchor" href="#zusammenfassende-vorwurfe-auswahl" aria-label="Permalink to &quot;Zusammenfassende Vorwürfe (Auswahl):&quot;">​</a></h3><ul><li><strong>Ibiza-Affäre:</strong> Geplante Umgehung von Parteienfinanzierungsregeln und Verkauf von Staatsanteilen.</li><li><strong>Postenschacher:</strong> Systematische Besetzung von Schlüsselpositionen in staatsnahen Betrieben und Institutionen nach Parteibuch.</li><li><strong>Inseraten-Affäre/Beinschab-Österreich-Skandal:</strong> Vorwürfe der Manipulation von Umfragen und Beeinflussung von Medien durch Steuergeld.</li></ul><hr><p><em>Quellen für diese Recherche: Berichte von GRECO (Europarat), Europäischer Kommission, Transparency International, OECD sowie internationale Medienberichte zu den jeweiligen Skandalen.</em></p>',20)])])}const p=n(a,[["render",s]]);export{g as __pageData,p as default};
